def text(n):
 s=(S/(n+'.html')).read_text(errors='replace');s=re.sub(r'<(script|style)\b.*?</\1>','',s,flags=re.S);return ' '.join(html.unescape(re.sub('<[^>]+>',' ',s)).split())
def title(n):return ' '.join(html.unescape(re.search(r'<title[^>]*>(.*?)</title>',(S/(n+'.html')).read_text(errors='replace'),re.S|re.I)[1]).split())
