def add(sid,src,quote,note,cat=None,sub='',level='Explicit'):
 assert quote in text(src),(src,quote)
 assert '\ufffd' not in quote
 eid=f'ae_b05_{sid}_{sum(e["school_id"]==sid for e in evidence)+1:02d}'
 evidence.append(dict(evidence_id=eid,school_id=sid,source_url=urls[src],page_title=title(src),accessed_date=DATE,quoted_text=quote,evidence_type='School website self-description',interpretation_note=note))
 if cat:codes.append(dict(code_id=f'ac_b05_{sid}_{sum(c["school_id"]==sid for c in codes)+1:02d}',school_id=sid,category=cat,subcategory=sub,coding_level=level,confidence='High' if level=='Explicit' else 'Medium',evidence_id=eid,coder_note='Assistant contextual review; codebook v1; 2026-10-27. '+note+' Website claim, not independently verified practice.',review_status='Reviewed'))
